set -e
cd "$(dirname "$0")"
mkdir site
mkdir other
head -c 200000 /dev/urandom > update.iso
head -c 65536 update.iso > site/first.iso
head -c 65536 update.iso > site/second.iso
head -c 65536 update.iso > site/third.iso
head -c 65536 update.iso > site/fourth.iso
head -c 65536 update.iso > site/offset.iso
head -c 65536 /dev/zero > site/zeros.iso
head -c 300000 /dev/zero > site/longer.iso
head -c 65536 update.iso > other/first.iso
surl --allow-anonymous --allow-uploads --directory site ftp://127.0.0.1:8080/ &
sleep 1
curl -sS -C - -T update.iso -w "%{size_upload}\n" ftp://127.0.0.1:8080/first.iso
kill $(jobs -p)
